def choose_move(observation):
    def sign(v):
        return 1 if v > 0 else (-1 if v < 0 else 0)

    def pos(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return None

    def nearest(targets, sx, sy):
        best = None
        best_d = None
        for t in targets or []:
            p = pos(t)
            if p is None:
                continue
            tx, ty = p
            d = abs(tx - sx) + abs(ty - sy)
            if best_d is None or d < best_d:
                best = (tx, ty)
                best_d = d
        return best

    env = observation.get("environment_name", "resource_collection")
    sp = pos(observation.get("self_position")) or (0, 0)
    sx, sy = sp
    op = pos(observation.get("opponent_position"))
    ox, oy = op if op is not None else (sx, sy)

    gw = observation.get("grid_width", 0) or 0
    gh = observation.get("grid_height", 0) or 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            if op is not None:
                return [sign(ox - sx), sign(oy - sy)]
            return [0, 0]
        corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
        target = max(corners, key=lambda c: abs(c[0] - ox) + abs(c[1] - oy))
        return [sign(target[0] - sx), sign(target[1] - sy)]

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        best = nearest(targets, sx, sy)
        if best is None:
            if op is not None:
                return [sign(ox - sx), sign(oy - sy)]
            return [0, 0]
        return [sign(best[0] - sx), sign(best[1] - sy)]

    resources = observation.get("resources") or observation.get("resource_positions") or []
    best = nearest(resources, sx, sy)
    if best is not None:
        return [sign(best[0] - sx), sign(best[1] - sy)]

    if op is not None:
        return [sign(ox - sx), sign(oy - sy)]

    return [0, 0]

